   if(!row){
     const now=Date.now();
     await env.DB.prepare('INSERT OR IGNORE INTO users (telegram_id,first_name,username,points,energy,max_energy,updated_at,created_at) VALUES (?,?,?,?,?,?,?,?)').bind(userId,'Miner','',0,START_ENERGY,START_ENERGY,now,now).run();
     row=await getUser(env,userId);
   }
