   if(rewardEventType==='valued'){
    const grant=await grantIfUnderLimit();
    if(!grant.ok){
      // keep event but do not mark rewarded
      return fail(grant.reason,409);
    }
    await env.DB.prepare('UPDATE monetag_ad_events SET rewarded_at=? WHERE ymid=?').bind(now,ymid).run();
    return json({ok:true,duplicate:false,reward:grant.reward,telegramId,ymid});
   }
